{
  "requirements": [
    {
      "text": "The system shall ensure that no account can have a negative balance.",
      "kaos_level": "tactical",
      "rationale": "This prevents financial discrepancies and ensures safe handling of funds."
    },
    {
      "text": "The system shall automatically withdraw funds from the related saving account if the checking account balance is insufficient.",
      "kaos_level": "tactical",
      "rationale": "This mitigates the risk of transaction failures due to insufficient funds."
    },
    {
      "text": "The system shall inform the user and terminate the transaction if the saving account balance is insufficient for the withdrawal.",
      "kaos_level": "operational",
      "rationale": "This provides immediate feedback to the user, enhancing safety in transaction handling."
    },
    {
      "text": "The system shall log all transactions with date, time, type, amount, and resulting balance.",
      "kaos_level": "operational",
      "rationale": "This ensures traceability and accountability of all financial transactions."
    },
    {
      "text": "The system shall implement secure PIN verification for user authentication.",
      "kaos_level": "tactical",
      "rationale": "This is essential for protecting user accounts against unauthorized access."
    },
    {
      "text": "The system shall provide a mechanism for safe degradation by allowing limited withdrawals during system maintenance.",
      "kaos_level": "strategic",
      "rationale": "This ensures continued access to funds even during unexpected downtimes."
    },
    {
      "text": "The system shall provide users with a clear summary of account status after each transaction.",
      "kaos_level": "operational",
      "rationale": "This enhances user understanding and trust in the system's reliability."
    }
  ]
}
